+// Audit log: every API request that changes data appends one entry.
+// Entries are never edited or deleted.
+
+/** Appends an audit entry and returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Lists all audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])]
+    .map((entry, idx) => ({ entry, idx }))
+    .sort((a, b) => b.entry.at.localeCompare(a.entry.at) || (b.entry.id ?? b.idx) - (a.entry.id ?? a.idx))
+    .map((x) => x.entry);
+}
