+// API key authentication and role-based access control.
+// Keys live in store.data.apiKeys as [{ key, name, role }].
+import { AppError } from "../errors.js";
+
+/** Supported API key roles. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+/** Finds the API key record for `key`, or throws 401 unauthorized. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || !key) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === key);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `apiKey.role` is in `allowedRoles`, or throws 403 forbidden. */
+export function authorize(apiKey, allowedRoles) {
+  if (!allowedRoles.includes(apiKey.role)) throw new AppError("forbidden");
+}
