@@ -0,0 +1,109 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { t } from "../src/i18n/messages.js";
+import { app, authHeaders, fresh, NOW, seed } from "./helpers.js";
+
+test("missing or unknown key answers 401 in the error shape", async () => {
+  const { handle } = app();
+  for (const headers of [{}, { Authorization: "Basic abc" }, { Authorization: "Bearer nope" }, { authorization: "Bearer " }]) {
+    const res = await handle({ path: "/items", headers });
+    assert.equal(res.status, 401);
+    assert.equal(res.body.error.code, "unauthorized");
+    assert.ok(res.body.error.message.length > 0);
+  }
+  assert.notEqual(t("unauthorized", "ko"), t("unauthorized", "en"));
+  assert.notEqual(t("forbidden", "ko"), t("forbidden", "en"));
+});
+
+test("seed has one key per role and lowercase authorization header works", async () => {
+  const keys = seed().apiKeys;
+  assert.deepEqual(
+    keys.map((k) => k.role).sort(),
+    ["cook", "manager", "viewer"],
+  );
+  const { handle } = app();
+  const viewerKey = keys.find((k) => k.role === "viewer").key;
+  const res = await handle({ path: "/items", headers: { authorization: `Bearer ${viewerKey}` } });
+  assert.equal(res.status, 200);
+});
+
+test("viewer may only read and cannot read /audit or mutate", async () => {
+  const { handle } = app();
+  const viewer = authHeaders("viewer");
+  assert.equal((await handle({ path: "/items", headers: viewer })).status, 200);
+  assert.equal((await handle({ path: "/batches", headers: viewer })).status, 200);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: viewer })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 4 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 1, reason: "spill" } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } },
+    { method: "POST", path: "/dishes", body: { name: "Soup", recipeId: 1, priceCents: 900 } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: viewer });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook may read and perform kitchen writes, but not manager actions", async () => {
+  const { handle } = app();
+  const cook = authHeaders("cook");
+  const manager = authHeaders("manager");
+
+  assert.equal((await handle({ path: "/items", headers: cook })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", headers: cook, body: { qty: 0.5, reason: "spill" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 4 } })).status, 201);
+
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } },
+    { method: "POST", path: "/dishes", body: { name: "Toast", recipeId: 2, priceCents: 500 } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: ["celery"] } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: cook });
+    assert.equal(res.status, 403);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("data-changing requests write audit entries listed newest first for managers", async () => {
+  let time = NOW;
+  const store = fresh();
+  const handle = createApp(store, { clock: () => time });
+  const cook = authHeaders("cook");
+  const manager = authHeaders("manager");
+
+  // GET and failed requests do not write audit entries
+  assert.equal((await handle({ path: "/items", headers: manager })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/dishes", headers: cook, body: { name: "X", recipeId: 1, priceCents: 500 } })).status, 403);
+  assert.equal((await handle({ path: "/audit", headers: manager })).body.length, 0);
+
+  // Two data-changing requests at different times
+  const firstAt = new Date(time).toISOString();
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } })).status, 201);
+
+  time += 5000;
+  const secondAt = new Date(time).toISOString();
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: manager, body: { portions: 4 } })).status, 200);
+
+  const res = await handle({ path: "/audit", headers: manager });
+  assert.equal(res.status, 200);
+  assert.equal(res.body.length, 2);
+  assert.deepEqual(
+    res.body.map(({ at, keyName, method, path, status }) => ({ at, keyName, method, path, status })),
+    [
+      { at: secondAt, keyName: "manager", method: "POST", path: "/recipes/1/cook", status: 200 },
+      { at: firstAt, keyName: "cook", method: "POST", path: "/temperatures", status: 201 },
+    ],
+  );
+});
